import requests
import pytest

class TestUserAPI:
    def ___(self):
        resp = requests.post("https://api.example.com/users",
            json={"name": "TestUser"})
        self.user_id = resp.json()["id"]

    def test_get_user(self):
        resp = requests.get(f"https://api.example.com/users/{self.user_id}")
        assert resp.status_code == 200

