import requests
failure_count = 0
circuit_open = False
for _ in range(5):
    if circuit_open:
        print("Circuit OPEN - skipping request")
        continue
    resp = requests.get("https://api.example.com/unstable")
    if resp.status_code >= 500:
        failure_count += 1
        if failure_count >= 3:
            circuit_open = True
    else:
        failure_count = 0

